<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import {amountCents,decimal,money,planTotal} from './tradeAmounts';
type Item={id:string;[key:string]:any};
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
type Access={contracts:{read:boolean;write:boolean};amend:boolean;receiptRead:boolean;receiptWrite:boolean;confirm:boolean;reverse:boolean;export:boolean};
const props=withDefaults(defineProps<{section:string;request:Request;download:(path:string,name:string)=>Promise<void>;access:Access;readonly:boolean;customerId?:string;quoteId?:string;contractId?:string;attachmentRead:boolean;attachmentWrite:boolean;customerWrite:boolean}>(),{customerId:'',quoteId:'',contractId:''});
const emit=defineEmits<{customer:[id:string];clearFilter:[];navigate:[section:string]}>();
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const busy=ref(false),error=ref(''),success=ref(''),items=ref<Item[]>([]),total=ref(0),page=ref(1),query=ref(''),status=ref(''),from=ref(today.slice(0,8)+'01'),to=ref(today),summary=ref<any>(null),asOf=ref('');
const contractMode=computed(()=>props.section==='contracts'),reportMode=computed(()=>props.section==='reconciliation');
const titles:Record<string,string>={contracts:'合同管理',receipts:'回款管理',reconciliation:'收款对账'};
const states:Record<string,string>={DRAFT:'草稿 / 待确认',SIGNED:'已签订',ACTIVE:'履行中',TERMINATED:'已终止',VOID:'已作废',CONFIRMED:'已确认',REVERSED:'已全额冲正'};
const actions:Record<string,string>={CREATED:'创建',UPDATED:'修改草稿',SIGN:'登记签订',ACTIVATE:'登记生效',TERMINATE:'终止',SIGNED:'登记签订',ACTIVE:'登记生效',TERMINATED:'终止',VOID:'作废',AMENDED:'受控变更',CONFIRMED:'确认到账',REVERSED:'登记冲正'};
const filters=computed(()=>new URLSearchParams({q:query.value,status:status.value,...(reportMode.value||!contractMode.value?{from:from.value,to:to.value}:{}),...(contractMode.value||reportMode.value?props.customerId?{customerId:props.customerId}:{}:{})}).toString());
const endpoint=computed(()=>contractMode.value?'/contracts':reportMode.value?'/trade/reconciliation':'/receipts');
const dialog=ref(''),modal=ref<HTMLElement|null>(null),selected=ref<Item|null>(null),snapshot=ref<any>(null),history=ref<Item[]>([]),historyPage=ref(1),historyTotal=ref(0),requestKey=ref('');
const historical=computed(()=>selected.value&&snapshot.value&&selected.value.version!==snapshot.value.version);
type Plan={id?:string;title:string;amount:string;dueDate:string;receivedCents?:number};
const contract=reactive({quoteId:'',quoteVersion:0,title:'',startDate:today,endDate:today.slice(0,4)+'-12-31',notes:'',reason:'',totalCents:0,plans:[] as Plan[]});
const quoteOptions=ref<Item[]>([]),optionsPage=ref(1),optionsTotal=ref(0),optionsQuery=ref(''),basis=ref<Item|null>(null),amending=ref(false);
const fundAccounts=ref<Item[]>([]);
const receipt=reactive({contractId:'',planId:'',amount:'',receivedDate:today,paymentReference:'',payerName:'',bankName:'',notes:'',proofAttachmentId:'',correctionOfReceiptId:'',fundAccountId:''});
const contractOptions=ref<Item[]>([]),receiptContract=ref<Item|null>(null),cashPage=ref(1),cashTotal=ref(0),cashQuery=ref('');
const decision=reactive({action:'',reason:'',date:today,amount:'',proofAttachmentId:''});
const files=ref<Item[]>([]),filePage=ref(1),fileTotal=ref(0),uploadFile=ref<File|null>(null),uploadKey=ref('');
const planPreview=computed(()=>{try{return {total:planTotal(contract.plans),error:''};}catch(e){return{total:0,error:(e as Error).message};}});
const canCreate=computed(()=>!props.readonly&&(contractMode.value?props.access.contracts.write&&props.customerWrite:props.access.receiptWrite));
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){const f=e as Error&{status?:number};error.value=f.message||'操作未完成';if([401,403,404].includes(f.status??0)){dialog.value='';selected.value=null;snapshot.value=null;items.value=[];summary.value=null;}}finally{busy.value=false;}}
async function load(){const r=await props.request<any>(endpoint.value+'?'+filters.value+`&page=${page.value}&pageSize=20`);items.value=r.items;total.value=r.total;summary.value=r.summary??null;asOf.value=r.asOf??'';}
function search(){page.value=1;run(load);}function turn(d:number){page.value+=d;run(load);}
async function quotesLoad(){const r=await props.request<any>(`/contracts/quote-options?page=${optionsPage.value}&pageSize=20&q=${encodeURIComponent(optionsQuery.value)}${props.customerId?'&customerId='+props.customerId:''}`);quoteOptions.value=r.items;optionsTotal.value=r.total;}
function quoteSearch(){optionsPage.value=1;run(quotesLoad);}function quoteTurn(d:number){optionsPage.value+=d;run(quotesLoad);}
async function chooseBasis(id:string){basis.value=await props.request<Item>('/contracts/quote-basis/'+id);const q=basis.value;contract.quoteId=q.id;contract.quoteVersion=q.version;contract.totalCents=q.totalCents;if(!selected.value){contract.title=q.title;contract.plans=[{title:'合同款',amount:decimal(q.totalCents),dueDate:contract.endDate}];}}
function chooseQuote(){run(()=>chooseBasis(contract.quoteId));}
function editContract(item?:Item,amend=false){run(async()=>{selected.value=item?await props.request<Item>('/contracts/'+item.id):null;snapshot.value=null;basis.value=null;amending.value=amend;const c=selected.value;Object.assign(contract,{quoteId:'',quoteVersion:0,title:c?.title??'',startDate:c?.startDate??today,endDate:c?.endDate??today.slice(0,4)+'-12-31',notes:c?.notes??'',reason:'',totalCents:c?.totalCents??0,plans:c?c.plans.map((p:any)=>({id:p.id,title:p.title,amount:decimal(p.amountCents),dueDate:p.dueDate,receivedCents:p.receivedCents})):[]});optionsPage.value=1;optionsQuery.value='';requestKey.value=crypto.randomUUID();dialog.value='contract-edit';if(!c||amend){await quotesLoad();if(props.quoteId&&!c)await chooseBasis(props.quoteId);}});}
function saveContract(){run(async()=>{if(planPreview.value.error)throw new Error(planPreview.value.error);if(planPreview.value.total!==contract.totalCents)throw new Error('各期收款金额之和须等于合同金额');const data={title:contract.title,startDate:contract.startDate,endDate:contract.endDate,notes:contract.notes,plans:contract.plans.map(p=>({id:p.id??null,title:p.title,amountCents:amountCents(p.amount),dueDate:p.dueDate})),...(!selected.value||amending.value?{quoteId:contract.quoteId,quoteExpectedVersion:contract.quoteVersion}:{}),...(selected.value?{expectedVersion:selected.value.version}:{}),...(amending.value?{reason:contract.reason}:{})};await props.request(selected.value?'/contracts/'+selected.value.id+(amending.value?'/amend':''):'/contracts',selected.value&&!amending.value?'PUT':'POST',data,selected.value&&!amending.value?{}:{'Idempotency-Key':requestKey.value});dialog.value='';await load();success.value=amending.value?'合同变更已保存，原报价与合同历史继续保留':'合同草稿已保存；签订后可登记回款';});}
function addPlan(){if(contract.plans.length<24)contract.plans.push({title:'第'+(contract.plans.length+1)+'期',amount:'',dueDate:contract.endDate});}
async function contractsLoad(){const r=await props.request<any>(`/contracts?collectable=true&page=${cashPage.value}&pageSize=20&q=${encodeURIComponent(cashQuery.value)}`);contractOptions.value=r.items;cashTotal.value=r.total;}
function cashSearch(){cashPage.value=1;run(contractsLoad);}function cashTurn(d:number){cashPage.value+=d;run(contractsLoad);}
async function chooseContract(id:string){receiptContract.value=await props.request<Item>('/contracts/'+id);receipt.contractId=id;receipt.planId=receiptContract.value.plans[0]?.id??'';}
function receiptContractChanged(){run(()=>chooseContract(receipt.contractId));}
function editReceipt(item?:Item,correction=false,contractId=''){run(async()=>{const r=item?await props.request<Item>('/receipts/'+item.id):null;fundAccounts.value=(await props.request<{items:Item[]}>('/finance/account-options')).items;selected.value=correction?null:r;snapshot.value=null;Object.assign(receipt,{fundAccountId:r?.fundAccountId??'',contractId:r?.contractId??contractId,planId:r?.planId??'',amount:r?decimal(r.amountCents):'',receivedDate:r?.receivedDate??today,paymentReference:r?.paymentReference??'',payerName:r?.payerName??'',bankName:r?.bankName??'',notes:correction?'更正原回款 '+r?.receiptNumber:r?.notes??'',proofAttachmentId:'',correctionOfReceiptId:correction?r!.id:r?.correctionOfReceiptId??''});receiptContract.value=null;cashPage.value=1;cashQuery.value='';requestKey.value=crypto.randomUUID();dialog.value='receipt-edit';await contractsLoad();if(receipt.contractId){const plan=receipt.planId;await chooseContract(receipt.contractId);if(plan)receipt.planId=plan;}if(r&&!correction)receipt.proofAttachmentId=r.proofAttachmentId??'';});}
function saveReceipt(){run(async()=>{await props.request(selected.value?'/receipts/'+selected.value.id:'/receipts',selected.value?'PUT':'POST',{...receipt,amountCents:amountCents(receipt.amount),amount:undefined,fundAccountId:receipt.fundAccountId||null,proofAttachmentId:receipt.proofAttachmentId||null,correctionOfReceiptId:receipt.correctionOfReceiptId||null,expectedVersion:selected.value?.version??0},selected.value?{}:{'Idempotency-Key':requestKey.value});dialog.value='';await load();success.value='登记已保存，需另一位获准经理确认后才计入已收款';});}
async function historyLoad(){const r=await props.request<any>(`/${contractMode.value?'contracts':'receipts'}/${selected.value!.id}/history?page=${historyPage.value}&pageSize=20`);history.value=r.items;historyTotal.value=r.total;}
async function fileLoad(){files.value=[];fileTotal.value=0;if(!props.attachmentRead||!selected.value)return;const contractId=contractMode.value?selected.value.id:selected.value.contractId;const r=await props.request<any>(`/attachments?contractId=${contractId}${contractMode.value?'':'&receiptId='+selected.value.id}&page=${filePage.value}&pageSize=20`);files.value=r.items;fileTotal.value=r.total;}
async function details(item:Item){selected.value=await props.request<Item>((contractMode.value?'/contracts/':'/receipts/')+item.id);snapshot.value=selected.value;historyPage.value=1;filePage.value=1;uploadFile.value=null;uploadKey.value=crypto.randomUUID();await historyLoad();await fileLoad();dialog.value='view';}
function show(item:Item){run(()=>details(item));}
function historyTurn(d:number){historyPage.value+=d;run(historyLoad);}function fileTurn(d:number){filePage.value+=d;run(fileLoad);}
function showVersion(v:number){run(async()=>{snapshot.value=v===selected.value?.version?selected.value:await props.request(`/${contractMode.value?'contracts':'receipts'}/${selected.value!.id}/versions/${v}`);});}
function openDecision(action:string){Object.assign(decision,{action,reason:'',date:today,amount:action==='reverse'?decimal(selected.value!.netCents):'',proofAttachmentId:selected.value?.proofAttachmentId??''});requestKey.value=crypto.randomUUID();dialog.value='decision';}
function applyDecision(){run(async()=>{const c=selected.value!,act=decision.action;const input={expectedVersion:c.version,reason:decision.reason,...(contractMode.value?act==='sign'?{signedDate:decision.date}:act==='activate'?{effectiveDate:decision.date}:{}:act==='reverse'?{amountCents:amountCents(decision.amount),reversalDate:decision.date,proofAttachmentId:decision.proofAttachmentId||null}:{proofAttachmentId:decision.proofAttachmentId||null})};const r=await props.request<Item>(`/${contractMode.value?'contracts':'receipts'}/${c.id}/${act}`,'POST',input,{'Idempotency-Key':requestKey.value});await load();await details(r);success.value=act==='confirm'?'已确认到账，合同及期次余额已更新':act==='reverse'?'冲正已入账并保留原记录，合同及期次余额已更新':'操作已保存并记录历史';});}
const canUpload=computed(()=>!props.readonly&&props.attachmentWrite&&selected.value&&!historical.value&&(contractMode.value?selected.value.canManage&&!['VOID','TERMINATED'].includes(selected.value.status):selected.value.canWrite||selected.value.canConfirm||selected.value.canReverse));
function chooseFile(e:Event){uploadFile.value=(e.target as HTMLInputElement).files?.[0]??null;uploadKey.value=crypto.randomUUID();}
function upload(){run(async()=>{if(!uploadFile.value||!selected.value)throw new Error('请选择附件');if(uploadFile.value.size>5242880)throw new Error('附件最多5MB');const c=selected.value,data=new FormData();data.set('customerId',c.customerId);data.set('contractId',contractMode.value?c.id:c.contractId);const target=contractMode.value?c:await props.request<Item>('/contracts/'+c.contractId);if(target.opportunityId)data.set('opportunityId',target.opportunityId);if(!contractMode.value)data.set('receiptId',c.id);data.set('file',uploadFile.value);await props.request('/attachments','POST',data,{'Idempotency-Key':uploadKey.value});uploadFile.value=null;uploadKey.value=crypto.randomUUID();await fileLoad();success.value='附件已保存，需下载核对后选择到账凭证';});}
function deleteFile(file:Item){run(async()=>{await props.request('/attachments/'+file.id+'?expectedVersion='+file.version,'DELETE');await fileLoad();success.value='可删除的草稿附件已移除';});}
function exportData(){run(async()=>{await props.download((reportMode.value?'/trade/reconciliation/export':'/contracts/export')+'?'+filters.value,reportMode.value?'收款对账.csv':'合同.csv');success.value='已导出当前筛选范围内可见记录';});}
let previousFocus:HTMLElement|null=null,previousOverflow='';watch(dialog,async(v,old)=>{if(v&&!old){previousFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}if(v){await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)')?.focus({preventScroll:true});}else{document.body.style.overflow=previousOverflow;previousFocus?.focus({preventScroll:true});}});
function keys(e:KeyboardEvent){if(!dialog.value)return;if(e.key==='Escape'&&!busy.value)dialog.value='';if(e.key==='Tab'){const nodes=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
onMounted(()=>{document.addEventListener('keydown',keys);run(load).then(()=>{if(props.contractId)show({id:props.contractId});else if(props.quoteId&&canCreate.value)editContract();});});onUnmounted(()=>{document.removeEventListener('keydown',keys);if(dialog.value)document.body.style.overflow=previousOverflow;});
</script>
<template>
 <section class="trade"><div class="page-heading"><div><span class="eyebrow">CONTRACTS & COLLECTIONS</span><h1>{{titles[section]}}</h1><p>{{contractMode?'以已批准报价为依据，管理签订、履行、变更及分期计划。':reportMode?'按业务日期核对到账与冲正，同时查看今天的应收余额。':'登记到账资料，由另一位获准经理核对确认，保留冲正轨迹。'}}</p></div><div class="trade-actions"><button class="btn secondary" :disabled="busy" @click="run(load)">刷新</button><button v-if="(contractMode||reportMode)&&access.export" class="btn secondary" :disabled="busy" @click="exportData">导出 CSV</button><button v-if="!reportMode&&canCreate" class="btn primary" :disabled="busy" @click="contractMode?editContract():editReceipt()">{{contractMode?'从批准报价建合同':'登记回款'}}</button></div></div>
 <p v-if="customerId" class="trade-note">正在查看指定客户的合同。<button class="text-button" @click="emit('clearFilter')">查看全部</button></p>
 <div v-if="error&&!dialog" class="trade-alert error" role="alert">{{error}}</div><div v-if="success" class="trade-alert ok" role="status">{{success}}</div><p v-if="readonly" class="trade-note">当前企业仅允许查看资料。</p>
 <form class="trade-filters card" @submit.prevent="search"><label>搜索<input v-model="query" maxlength="100" :placeholder="contractMode||reportMode?'合同编号、主题或客户':'回款编号、凭证号或客户'"/></label><label>状态<select v-model="status"><option value="">全部状态</option><option v-for="s in (contractMode?['DRAFT','SIGNED','ACTIVE','TERMINATED','VOID']:reportMode?['SIGNED','ACTIVE','TERMINATED']:['DRAFT','CONFIRMED','REVERSED','VOID'])" :key="s" :value="s">{{states[s]}}</option></select></label><template v-if="!contractMode"><label>开始日期<input v-model="from" type="date" min="2000-01-01" :max="today" required/></label><label>结束日期<input v-model="to" type="date" min="2000-01-01" :max="today" required/></label></template><button class="btn secondary" :disabled="busy">查询</button></form>
 <template v-if="reportMode&&summary"><div class="trade-summary"><article v-for="m in [{key:'totalCents',label:'当前合同总额'},{key:'receivedCents',label:'当前净已收'},{key:'remainingCents',label:'当前未收'},{key:'overdueCents',label:'当前逾期未收'},{key:'periodReceivedCents',label:'期间确认到账'},{key:'periodReversedCents',label:'期间冲正'},{key:'periodNetCents',label:'期间净收款'}]" :key="m.key" class="card"><span>{{m.label}}</span><strong>{{money(summary[m.key])}}</strong></article></div><p class="trade-note">余额核对日：{{asOf}}。期间金额按到账 / 冲正业务日期统计；待确认登记不计入已收。已终止合同的未结应收继续保留。</p></template>
 <div class="card trade-table"><div class="table-scroll"><table><thead><tr><th>{{contractMode||reportMode?'合同':'回款'}}</th><th>客户</th><th>状态</th><th>金额</th><th>{{contractMode||reportMode?'净已收 / 未收':'到账日期 / 凭证'}}</th><th v-if="reportMode">期间净额 / 逾期</th><th>操作</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td><strong>{{r.contractNumber||r.receiptNumber}}</strong><small>{{r.title||r.planTitleSnapshot}}</small></td><td><button class="text-button" @click="emit('customer',r.customerId)">{{r.customerNameSnapshot}}</button></td><td><span class="badge neutral">{{states[r.status]}}</span><small v-if="r.expired">合同期已结束</small></td><td>{{money(r.totalCents??r.amountCents)}}</td><td v-if="contractMode||reportMode">{{money(r.receivedCents)}} / {{money(r.remainingCents)}}</td><td v-else>{{r.receivedDate}}<small>{{r.paymentReference}}</small><small>净已收 {{money(r.netCents)}}</small></td><td v-if="reportMode">{{money(r.periodNetCents)}} / {{money(r.overdueCents)}}</td><td><button class="text-button" :disabled="busy" @click="reportMode?emit('navigate','contracts'):show(r)">{{reportMode?'进入合同管理':'查看'}}</button><button v-if="r.canWrite&&!readonly" class="text-button" :disabled="busy" @click="contractMode?editContract(r):editReceipt(r)">编辑</button></td></tr></tbody></table></div><p v-if="!items.length" class="trade-empty">{{busy?'正在读取…':'当前筛选下没有记录'}}</p><div class="trade-pages"><span>共 {{total}} 条 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page===1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div></div>
 <Teleport to="body"><div v-if="dialog" class="trade-backdrop" @click.self="!busy&&(dialog='')"><section ref="modal" class="trade-dialog" role="dialog" aria-modal="true" aria-labelledby="trade-dialog-title"><header><h2 id="trade-dialog-title">{{dialog==='view'?(contractMode?'合同详情':'回款详情'):dialog==='contract-edit'?(amending?'登记受控合同变更':selected?'编辑合同草稿':'从批准报价建合同'):dialog==='receipt-edit'?(receipt.correctionOfReceiptId?'建立更正登记':selected?'编辑待确认回款':'登记回款'):{sign:'登记合同签订',activate:'登记合同生效',terminate:'终止合同',void:'作废草稿',confirm:'核对并确认到账',reverse:'登记冲正'}[decision.action]}}</h2><button type="button" class="btn secondary" :disabled="busy" aria-label="关闭弹窗" @click="dialog=''">关闭</button></header>
 <form v-if="dialog==='contract-edit'||dialog==='receipt-edit'||dialog==='decision'" class="trade-form" @submit.prevent="dialog==='contract-edit'?saveContract():dialog==='receipt-edit'?saveReceipt():applyDecision()"><div class="trade-body"><div v-if="error" class="trade-alert error" role="alert">{{error}}</div><fieldset :disabled="busy||readonly"><template v-if="dialog==='contract-edit'"><div v-if="!selected||amending" class="trade-block"><h3>选择有效的已批准报价</h3><div class="trade-actions"><input v-model="optionsQuery" maxlength="100" placeholder="搜索报价编号或主题"/><button type="button" class="btn secondary" @click="quoteSearch">搜索</button></div><select v-model="contract.quoteId" required @change="chooseQuote"><option value="">选择报价</option><option v-if="basis&&!quoteOptions.some(q=>q.id===basis?.id)" :value="basis.id">{{basis.quoteNumber}} · {{basis.title}}</option><option v-for="q in quoteOptions" :key="q.id" :value="q.id">{{q.quoteNumber}} · {{q.customerNameSnapshot}} · {{money(q.totalCents)}}</option></select><div class="trade-pages"><span>共 {{optionsTotal}} 条</span><button type="button" class="text-button" :disabled="optionsPage===1" @click="quoteTurn(-1)">上一页</button><button type="button" class="text-button" :disabled="optionsPage*20>=optionsTotal" @click="quoteTurn(1)">下一页</button></div><p>变更报价需属于原合同同一客户及商机，新的报价版本须重新审批。</p></div><div class="trade-grid"><label class="wide">合同主题<input v-model="contract.title" required maxlength="200"/></label><label>开始日期<input v-model="contract.startDate" type="date" min="2000-01-01" max="2100-12-31" required/></label><label>结束日期<input v-model="contract.endDate" type="date" min="2000-01-01" max="2100-12-31" required/></label><label class="wide">合同备注<textarea v-model="contract.notes" rows="3" maxlength="4000"/></label><label v-if="amending" class="wide">变更原因<textarea v-model="contract.reason" maxlength="500" required rows="3"/></label></div><div class="trade-block"><h3>分期收款计划 · 合同含税总额 {{money(contract.totalCents)}}</h3><p>总额来自批准报价。已收期次须保留，金额不能低于该期净已收；有待确认回款的期次也不能移除。</p><div v-for="(p,i) in contract.plans" :key="p.id||i" class="trade-plan"><label>第 {{i+1}} 期<input v-model="p.title" maxlength="100" required placeholder="期次名称"/></label><label>金额（元）<input v-model="p.amount" inputmode="decimal" required placeholder="0.00"/><small v-if="p.receivedCents!=null">净已收 {{money(p.receivedCents)}}</small></label><label>应收日期<input v-model="p.dueDate" type="date" min="2000-01-01" max="2100-12-31" required/></label><button type="button" class="text-button" :disabled="contract.plans.length===1||!!p.receivedCents" @click="contract.plans.splice(i,1)">移除</button></div><div class="trade-actions"><button type="button" class="btn secondary" :disabled="contract.plans.length>=24" @click="addPlan">添加期次</button><span>{{planPreview.error||('计划合计 '+money(planPreview.total))}}</span></div></div></template>
 <template v-else-if="dialog==='receipt-edit'"><label>资金归集账户<select v-model="receipt.fundAccountId"><option value="">暂不归集（单独列示）</option><option v-for="a in fundAccounts.filter(a=>a.active||a.id===receipt.fundAccountId)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><p class="trade-note">登记不会增加已收款，确认后才更新余额。到账凭证号在本企业内去空格、不区分大小写防重复。</p><div v-if="!selected&&!receipt.correctionOfReceiptId" class="trade-block"><div class="trade-actions"><input v-model="cashQuery" maxlength="100" placeholder="搜索已签订合同"/><button type="button" class="btn secondary" @click="cashSearch">搜索</button></div><label>合同<select v-model="receipt.contractId" required @change="receiptContractChanged"><option value="">选择合同</option><option v-if="receiptContract&&!contractOptions.some(c=>c.id===receiptContract?.id)" :value="receiptContract.id">{{receiptContract.contractNumber}}</option><option v-for="c in contractOptions" :key="c.id" :value="c.id">{{c.contractNumber}} · {{c.customerNameSnapshot}} · 未收 {{money(c.remainingCents)}}</option></select></label><div class="trade-pages"><span>共 {{cashTotal}} 条</span><button type="button" class="text-button" :disabled="cashPage===1" @click="cashTurn(-1)">上一页</button><button type="button" class="text-button" :disabled="cashPage*20>=cashTotal" @click="cashTurn(1)">下一页</button></div></div><p v-else>{{receiptContract?.contractNumber}} · {{receiptContract?.customerNameSnapshot}}</p><div class="trade-grid"><label class="wide">收款期次<select v-model="receipt.planId" required><option value="">选择期次</option><option v-for="p in receiptContract?.plans??[]" :key="p.id" :value="p.id">{{p.title}} · 应收 {{money(p.amountCents)}} · 净已收 {{money(p.receivedCents)}}</option></select></label><label>到账金额（元）<input v-model="receipt.amount" inputmode="decimal" required/></label><label>到账日期<input v-model="receipt.receivedDate" type="date" min="2000-01-01" :max="today" required/></label><label class="wide">到账凭证号<input v-model="receipt.paymentReference" maxlength="120" required :readonly="!!receipt.correctionOfReceiptId"/></label><label>付款单位<input v-model="receipt.payerName" maxlength="120"/></label><label>收款银行<input v-model="receipt.bankName" maxlength="120"/></label><label class="wide">登记备注<textarea v-model="receipt.notes" maxlength="2000" rows="3"/></label></div><p class="trade-note">先保存登记，再到详情上传凭证附件并核对确认。更正登记保留与原回款的关联。</p></template>
 <template v-else><p class="trade-note">{{selected?.contractNumber||selected?.receiptNumber}} · {{selected?.title||selected?.customerNameSnapshot}}</p><p v-if="decision.action==='confirm'">确认前请核对银行到账、金额、期次与凭证。登记人与确认人须为不同账号，确认后不能直接改写金额。</p><p v-if="decision.action==='reverse'">冲正用于纠正账务记录，不会向银行发起退款。原到账记录继续保留。</p><p v-if="decision.action==='terminate'">终止合同会保留未结应收款，已有到账及冲正继续参与对账。</p><div class="trade-grid"><label v-if="['sign','activate','reverse'].includes(decision.action)">业务日期<input v-model="decision.date" type="date" min="2000-01-01" :max="today" required/></label><label v-if="decision.action==='reverse'">冲正金额（元）<input v-model="decision.amount" inputmode="decimal" required/><small>最多 {{money(selected?.netCents)}}</small></label><label class="wide">{{['void','terminate','reverse'].includes(decision.action)?'必填原因':'核对备注'}}<textarea v-model="decision.reason" maxlength="500" rows="3" :required="['void','terminate','reverse'].includes(decision.action)"/></label><label v-if="!contractMode&&attachmentRead" class="wide">凭证附件<select v-model="decision.proofAttachmentId"><option value="">{{decision.action==='confirm'?'沿用登记所选凭证 / 无附件':'不选择附件'}}</option><option v-for="f in files.filter(f=>f.status==='READY')" :key="f.id" :value="f.id">{{f.filename||f.fileName}}</option></select></label></div></template></fieldset></div><footer><span>保存后会保留操作人与历史版本。</span><button type="button" class="btn secondary" :disabled="busy" @click="dialog=selected?'view':'';error='' ">{{selected?'返回详情':'关闭'}}</button><button class="btn primary" :disabled="busy||readonly">{{busy?'处理中…':'确认保存'}}</button></footer></form>
 <template v-else-if="dialog==='view'&&selected&&snapshot"><div class="trade-body"><div v-if="error" class="trade-alert error" role="alert">{{error}}</div><p v-if="historical" class="trade-note">正在查看历史版本 {{snapshot.version}}，当前版本 {{selected.version}}。历史金额与计划是保存当时的业务资料。</p><div class="trade-detail"><div><span>编号 / 状态</span><strong>{{snapshot.contractNumber||snapshot.receiptNumber}} · {{states[snapshot.status]}}</strong></div><div><span>客户 / 负责人或登记人</span><strong>{{snapshot.customerNameSnapshot}} · {{snapshot.ownerNameSnapshot||snapshot.creatorNameSnapshot}}</strong></div><div><span>{{contractMode?'合同含税总额':'登记金额'}}</span><strong>{{money(snapshot.totalCents??snapshot.amountCents)}}</strong></div><div v-if="!historical&&access.receiptRead"><span>{{contractMode?'当前净已收 / 未收':'当前净额 / 已冲正'}}</span><strong>{{money(contractMode?snapshot.receivedCents:snapshot.netCents)}} / {{money(contractMode?snapshot.remainingCents:snapshot.reversedCents)}}</strong></div><div v-if="contractMode"><span>合同期 / 签订 / 生效</span><strong>{{snapshot.startDate}} 至 {{snapshot.endDate}} · {{snapshot.signedDate||'未签订'}} / {{snapshot.effectiveDate||'未生效'}}</strong></div><div v-else><span>到账日期 / 凭证号 / 核对人</span><strong>{{snapshot.receivedDate}} · {{snapshot.paymentReference}} · {{snapshot.confirmerNameSnapshot||'待核对'}}</strong></div></div><p>{{snapshot.notes||'无备注'}}</p>
 <div v-if="!historical&&!readonly" class="trade-actions trade-block"><template v-if="contractMode"><button v-if="selected.canWrite" class="btn secondary" :disabled="busy" @click="editContract(selected)">编辑草稿</button><button v-if="selected.canManage&&selected.status==='DRAFT'" class="btn primary" :disabled="busy" @click="openDecision('sign')">登记签订</button><button v-if="selected.canManage&&selected.status==='SIGNED'" class="btn primary" :disabled="busy" @click="openDecision('activate')">登记生效</button><button v-if="selected.canAmend" class="btn secondary" :disabled="busy" @click="editContract(selected,true)">受控变更</button><button v-if="selected.canManage&&['SIGNED','ACTIVE'].includes(selected.status)" class="btn secondary" :disabled="busy" @click="openDecision('terminate')">终止合同</button><button v-if="selected.canWrite" class="btn secondary" :disabled="busy" @click="openDecision('void')">作废草稿</button></template><template v-else><button v-if="selected.canWrite" class="btn secondary" :disabled="busy" @click="editReceipt(selected)">编辑登记</button><button v-if="selected.canConfirm" class="btn primary" :disabled="busy" @click="openDecision('confirm')">核对并确认到账</button><button v-if="selected.canReverse" class="btn secondary" :disabled="busy" @click="openDecision('reverse')">登记冲正</button><button v-if="selected.canWrite" class="btn secondary" :disabled="busy" @click="openDecision('void')">作废登记</button><button v-if="selected.status==='REVERSED'&&access.receiptWrite" class="btn secondary" :disabled="busy" @click="editReceipt(selected,true)">建立更正登记</button></template></div>
 <div v-if="contractMode" class="trade-block"><h3>收款计划</h3><div class="table-scroll"><table><thead><tr><th>期次</th><th>金额</th><th>应收日期</th><th v-if="!historical&&access.receiptRead">净已收</th></tr></thead><tbody><tr v-for="p in (snapshot.plans??[]).filter((p:any)=>p.active!==false)" :key="p.id"><td>{{p.title}}</td><td>{{money(p.amountCents)}}</td><td>{{p.dueDate}}</td><td v-if="!historical&&access.receiptRead">{{money(p.receivedCents)}}</td></tr></tbody></table></div><h3>批准报价明细 · {{snapshot.quoteSnapshot?.quoteNumber}} · v{{snapshot.currentQuoteVersion}}</h3><div class="table-scroll"><table><thead><tr><th>产品 / 服务</th><th>数量</th><th>单价</th><th>含税金额</th></tr></thead><tbody><tr v-for="l in snapshot.quoteSnapshot?.lines??[]" :key="l.id"><td>{{l.nameSnapshot}}</td><td>{{l.quantity}} {{l.unitSnapshot}}</td><td>{{money(l.unitPriceCents)}}</td><td>{{money(l.amountCents)}}</td></tr></tbody></table></div></div>
 <div v-else-if="snapshot.reversals?.length" class="trade-block"><h3>不可改写的冲正记录</h3><article v-for="v in snapshot.reversals" :key="v.id" class="trade-history"><strong>{{v.reversalNumber}} · {{money(v.amountCents)}}</strong><span>{{v.reversalDate}} · {{v.actorNameSnapshot}}</span><p>{{v.reason}}</p></article></div>
 <div class="trade-block"><h3>版本与操作历史</h3><div v-for="h in history" :key="h.id" class="trade-history"><button class="text-button" :disabled="busy" @click="showVersion(h.businessVersion)">v{{h.businessVersion}} · {{actions[h.action]||h.action}}</button><span>{{h.actorNameSnapshot}} · {{h.reason}}</span></div><div class="trade-pages"><span>共 {{historyTotal}} 条</span><button class="text-button" :disabled="busy||historyPage===1" @click="historyTurn(-1)">上一页</button><button class="text-button" :disabled="busy||historyPage*20>=historyTotal" @click="historyTurn(1)">下一页</button></div></div>
 <div v-if="attachmentRead&&!historical" class="trade-block"><h3>{{contractMode?'合同文件':'到账 / 冲正凭证附件'}}</h3><p>签订后合同附件、已用于到账或冲正的凭证会保留，禁止删除。文件按当前合同与回款权限访问。</p><div v-for="f in files" :key="f.id" class="trade-history"><span>{{f.filename||f.fileName}} · {{f.status}}</span><button class="text-button" :disabled="busy||f.status!=='READY'" @click="run(()=>download('/attachments/'+f.id+'/download',f.filename||f.fileName))">下载</button><button v-if="f.canWrite&&!readonly" class="text-button" :disabled="busy" @click="deleteFile(f)">删除草稿附件</button></div><div class="trade-pages"><span>共 {{fileTotal}} 条</span><button class="text-button" :disabled="busy||filePage===1" @click="fileTurn(-1)">上一页</button><button class="text-button" :disabled="busy||filePage*20>=fileTotal" @click="fileTurn(1)">下一页</button></div><div v-if="canUpload" class="trade-actions"><input type="file" aria-label="选择合同或回款附件" accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.xlsx,.docx" @change="chooseFile"/><button class="btn secondary" :disabled="busy||!uploadFile" @click="upload">上传附件</button></div></div></div><footer><button class="btn secondary" :disabled="busy" @click="dialog=''">关闭详情</button></footer></template>
 </section></div></Teleport></section>
</template>
<style scoped>
.trade-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.trade-alert{padding:13px 16px;border-radius:7px;line-height:1.7;overflow-wrap:anywhere;margin-bottom:16px}.trade-alert.error{background:#fff0f1;color:#a52836}.trade-alert.ok{background:#eaf5ed;color:#286045}.trade-note,.trade-block p{font-size:13px;color:#62766a;line-height:1.8}.trade-filters{padding:18px;display:flex;gap:15px;align-items:end;flex-wrap:wrap;margin:20px 0}.trade label{font-size:13px;display:flex;flex-direction:column;gap:7px}.trade-filters label:first-child{flex:1;min-width:220px}.trade input,.trade select,.trade textarea,.trade-dialog input,.trade-dialog select,.trade-dialog textarea{min-width:0;width:100%;padding:10px;border:1px solid #cbd8ce;border-radius:6px;font:inherit;background:#fff;color:#263f2d}.trade-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin-bottom:18px}.trade-summary article{padding:20px}.trade-summary strong,.trade-summary span{display:block;overflow-wrap:anywhere}.trade-summary span{font-size:12px;color:#62766a;margin-bottom:12px}.trade-summary strong{font-size:21px}.trade-table{overflow:hidden}.trade td small{display:block;color:#6c7c71;font-size:12px;margin-top:6px}.trade-pages{display:flex;gap:12px;align-items:center;padding:15px;flex-wrap:wrap;font-size:12px;color:#62766a}.trade-pages span{margin-right:auto}.trade-empty{text-align:center;padding:40px;color:#62766a}.trade-backdrop{position:fixed;inset:0;z-index:10000;background:#10231d88;display:flex;justify-content:center;align-items:center;padding:24px;isolation:isolate}.trade-dialog{background:#fff;width:min(1000px,100%);max-height:calc(100dvh - 48px);min-height:0;border-radius:12px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 70px #162d3033;color:#263f2d;font-size:14px}.trade-dialog header,.trade-dialog footer{flex-shrink:0;display:flex;gap:14px;justify-content:space-between;align-items:center;padding:20px 24px;border-bottom:1px solid #e0e8e2}.trade-dialog h2{font-size:20px}.trade-dialog footer{border-bottom:0;border-top:1px solid #e0e8e2;justify-content:flex-end}.trade-dialog footer span{margin-right:auto;font-size:12px;color:#62766a}.trade-form{display:flex;flex-direction:column;min-height:0;overflow:hidden}.trade-body{padding:24px;min-height:0;overflow-y:auto;overscroll-behavior:contain}.trade-dialog fieldset{padding:0;border:0;min-width:0}.trade-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:20px 0}.trade-grid .wide{grid-column:1/-1}.trade-dialog label{display:flex;flex-direction:column;gap:8px;font-size:13px}.trade-dialog .trade-actions input{flex:1;min-width:170px}.trade-block{border:1px solid #dbe6de;border-radius:8px;padding:18px;margin:18px 0}.trade-block h3{font-size:15px;margin-bottom:13px}.trade-plan{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:12px;align-items:end;margin:16px 0}.trade-detail{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:20px;background:#eef5ef;border-radius:8px}.trade-detail span,.trade-detail strong{display:block;overflow-wrap:anywhere}.trade-detail span{font-size:12px;color:#62766a;margin-bottom:8px}.trade-history{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid #e4ece6}.trade-history p{width:100%;margin:0}.trade-history span{font-size:12px;color:#62766a}.trade-dialog small{color:#62766a;line-height:1.7}.trade-dialog td,.trade-dialog th{padding:12px;font-size:13px}.trade-dialog table{width:100%;border-collapse:collapse;text-align:left}.trade-dialog th{background:#f3f6f3}.trade-dialog td{border-bottom:1px solid #e4ece6}
@media(max-width:700px){.trade-backdrop{padding:12px}.trade-dialog{max-height:calc(100dvh - 24px)}.trade-body{padding:18px}.trade-grid,.trade-detail{grid-template-columns:1fr}.trade-plan{grid-template-columns:1fr 1fr}.trade-dialog footer{flex-wrap:wrap;padding:16px}.trade-dialog footer span{width:100%}}
</style>
